(()=>{'use strict';
// CIP comparisons for this deliberately bounded substituent bank.
const groups={H:{label:'H',rank:[1],color:'#d4ddc9'},F:{label:'F',rank:[9],color:'#91bc76'},Cl:{label:'Cl',rank:[17],color:'#6caa84'},Br:{label:'Br',rank:[35],color:'#c48a61'},I:{label:'I',rank:[53],color:'#a594c4'},CH3:{label:'CH₃',rank:[6,1,1,1],color:'#d0b45c'},C2H5:{label:'C₂H₅',rank:[6,6,1,1],color:'#859fc8'},CH2OH:{label:'CH₂OH',rank:[6,8,1,1],color:'#c97972'}};
const presets={butene:['CH3','H','CH3','H'],pentene:['CH3','H','C2H5','H'],difluoro:['F','H','F','H'],mixed:['Br','Cl','F','H'],tie:['C2H5','CH3','Br','H'],propene:['H','H','CH3','H'],dimethyl:['CH3','CH3','H','CH3']};
function compare(a,b){const x=groups[a].rank,y=groups[b].rank;for(let i=0;i<Math.max(x.length,y.length);i++){const d=(x[i]||0)-(y[i]||0);if(d)return Math.sign(d);}return 0;}
function classify(labels){const a=compare(labels[0],labels[1]),b=compare(labels[2],labels[3]),high=[a===0?null:a>0?0:1,b===0?null:b>0?2:3];return {high,possible:!!a&&!!b,type:!a||!b?'Neither E nor Z':(high[0]===0)===(high[1]===2)?'Z':'E',duplicate:!a&&!b?'both carbons':!a?'carbon 1':!b?'carbon 2':''};}
const I=()=>[[1,0,0],[0,1,0],[0,0,1]],dot=(a,b)=>a.reduce((s,v,i)=>s+v*b[i],0),trans=a=>a[0].map((_,i)=>a.map(r=>r[i])),mul=(a,b)=>a.map(row=>trans(b).map(col=>dot(row,col))),apply=(m,v)=>m.map(row=>dot(row,v));
function rotation(axis,t){const c=Math.cos(t),s=Math.sin(t);return axis==='x'?[[1,0,0],[0,c,-s],[0,s,c]]:axis==='y'?[[c,0,s],[0,1,0],[-s,0,c]]:[[c,-s,0],[s,c,0],[0,0,1]];}
const height=Math.sqrt(3)*.7,geometry=[[-.65,0,0],[.65,0,0],[-1.35,height,0],[-1.35,-height,0],[1.35,height,0],[1.35,-height,0]];
class Model{constructor(){this.labels=presets.butene.slice();this.view=I();}get result(){return classify(this.labels);}swap(side){const a=side*2;[this.labels[a],this.labels[a+1]]=[this.labels[a+1],this.labels[a]];}rotate(dx,dy,dz=0){this.view=mul(rotation('z',dz),mul(rotation('y',dx),mul(rotation('x',dy),this.view)));}reset(){this.view=I();}}
if(typeof module!=='undefined'&&module.exports)module.exports={groups,presets,compare,classify,Model,geometry,apply};if(typeof document==='undefined')return;
const $=id=>document.getElementById('ez-'+id);if(!$('game'))return;const model=new Model();let showPriorities=false,zoom=1,drag=null;
function draw(){const canvas=$('canvas'),w=canvas.clientWidth||760,h=420,dpr=Math.min(window.devicePixelRatio||1,2);if(canvas.width!==Math.round(w*dpr)||canvas.height!==h*dpr){canvas.width=Math.round(w*dpr);canvas.height=h*dpr;}const ctx=canvas.getContext('2d');if(!ctx)return;ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,w,h);const size=Math.min(w/4.3,105)*zoom,project=v=>{const a=apply(model.view,v),p=5/(5-.6*a[2]);return {x:w/2+a[0]*size*p,y:h/2-a[1]*size*p,z:a[2],p}},points=geometry.map(project),items=[],result=model.result;
for(const [a,b]of [[0,2],[0,3],[1,4],[1,5]])items.push({kind:'bond',p:points[a],q:points[b],z:(points[a].z+points[b].z)/2});for(const y of [-.055,.055]){const p=project([-.65,y,0]),q=project([.65,y,0]);items.push({kind:'bond',p,q,z:(p.z+q.z)/2});}
points.forEach((p,i)=>{const g=i<2?{label:i===0?'C₁':'C₂',color:'#607b57'}:groups[model.labels[i-2]];items.push({kind:'atom',p,z:p.z,g,index:i,high:i>=2&&result.high.includes(i-2)});});items.sort((a,b)=>a.z-b.z||(a.kind==='bond'?-1:1));
for(const item of items){ctx.save();if(item.kind==='bond'){ctx.beginPath();ctx.moveTo(item.p.x,item.p.y);ctx.lineTo(item.q.x,item.q.y);ctx.strokeStyle='#91a183';ctx.lineWidth=6;ctx.lineCap='round';ctx.stroke();}else{const {x,y,p}=item.p,r=(item.g.label.length>3?31:26)*p*Math.sqrt(zoom);if(showPriorities&&item.high){ctx.beginPath();ctx.arc(x,y,r+7,0,Math.PI*2);ctx.strokeStyle='#b28c38';ctx.lineWidth=3;ctx.stroke();}ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);const grad=ctx.createRadialGradient(x-r*.3,y-r*.35,1,x,y,r);grad.addColorStop(0,'#fff');grad.addColorStop(.4,item.g.color);grad.addColorStop(1,item.g.color);ctx.fillStyle=grad;ctx.shadowColor='#30452325';ctx.shadowBlur=7;ctx.shadowOffsetY=3;ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#62795155';ctx.lineWidth=1;ctx.stroke();ctx.fillStyle=item.index<2?'#fff':'#2e4631';ctx.font=`600 ${item.g.label.length>3?13:17}px system-ui`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(item.g.label,x,y);}ctx.restore();}ctx.fillStyle='#829176';ctx.font='12px system-ui';ctx.fillText('3D · drag to rotate the whole molecule',15,h-17);}
function ranking(side){const a=side*2,x=model.labels[a],y=model.labels[a+1],d=compare(x,y);if(!d)return 'C'+(side+1)+': identical groups — no priority distinction.';const hi=d>0?x:y,lo=d>0?y:x;const explanation=groups[hi].rank[0]===groups[lo].rank[0]?'Both attach through carbon; compare the next atoms.':'Compare atomic numbers of the directly attached atoms.';return 'C'+(side+1)+': '+groups[hi].label+' > '+groups[lo].label+'. '+explanation;}
function render(){const r=model.result;$('result').textContent=r.type;$('reason').textContent=r.possible?(r.type==='Z'?'Higher-priority groups are on the same side of C=C.':'Higher-priority groups are on opposite sides of C=C.'):'E/Z is not possible: '+r.duplicate+' has two identical groups.';$('priority-details').hidden=!showPriorities;$('priorities').textContent=showPriorities?'Hide priorities':'Show priorities';$('priorities').setAttribute('aria-pressed',String(showPriorities));$('rank-left').textContent=ranking(0);$('rank-right').textContent=ranking(1);draw();}
function sync(){model.labels.forEach((v,i)=>$('group-'+i).value=v);document.dispatchEvent(new Event('chemi-controls-sync'));}
$('preset').addEventListener('change',e=>{if(presets[e.target.value]){model.labels=presets[e.target.value].slice();model.reset();sync();render();}});for(let i=0;i<4;i++)$('group-'+i).addEventListener('change',e=>{model.labels[i]=e.target.value;$('preset').value='custom';sync();render();});for(let side=0;side<2;side++)$('swap-'+side).addEventListener('click',()=>{model.swap(side);sync();render();});$('priorities').addEventListener('click',()=>{showPriorities=!showPriorities;render();});$('reset').addEventListener('click',()=>{model.reset();zoom=1;$('zoom').value=100;render();});$('zoom').addEventListener('input',e=>{zoom=Number(e.target.value)/100;render();});$('roll-left').addEventListener('click',()=>{model.rotate(0,0,-Math.PI/12);render();});$('roll-right').addEventListener('click',()=>{model.rotate(0,0,Math.PI/12);render();});
const canvas=$('canvas');canvas.addEventListener('pointerdown',e=>{if(e.button!==undefined&&e.button!==0)return;e.preventDefault();drag={x:e.clientX,y:e.clientY,pointer:e.pointerId};canvas.setPointerCapture(e.pointerId);canvas.focus();});canvas.addEventListener('pointermove',e=>{if(!drag||drag.pointer!==e.pointerId)return;model.rotate((e.clientX-drag.x)*.012,(e.clientY-drag.y)*.012);drag.x=e.clientX;drag.y=e.clientY;render();});function stop(e){if(drag?.pointer===e.pointerId){drag=null;if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId);}}canvas.addEventListener('pointerup',stop);canvas.addEventListener('pointercancel',stop);canvas.addEventListener('keydown',e=>{const v={ArrowLeft:[-.15,0,0],ArrowRight:[.15,0,0],ArrowUp:[0,-.15,0],ArrowDown:[0,.15,0],q:[0,0,-.15],e:[0,0,.15]}[e.key];if(v){e.preventDefault();model.rotate(...v);render();}});window.addEventListener('resize',draw);window.addEventListener('hashchange',()=>requestAnimationFrame(draw));sync();render();
})();
